// Visibility score = how many measured LLMs recommend us, plus share of voice.
const item = items[0].json;
const rec = (item.overall && item.overall.recommended_count) || 0;
const total = (item.overall && item.overall.llm_count) || 0;
const sov = (item.overall && item.overall.share_of_voice_pct) || 0;
const score = Math.round(rec * 20 + (sov || 0)); // simple, transparent blend

const store = $getWorkflowStaticData('global');
const prev = typeof store.lastVisibilityScore === 'number' ? store.lastVisibilityScore : null;
store.lastVisibilityScore = score;

const drop = prev === null ? 0 : prev - score;
const dropped = drop >= 1;           // any decrease vs last run
const slipped = item.slipped === true;     // recommended by NO LLM
const overtaken = item.overtaken === true; // a competitor leads

return [{ json: {
  brand: item.brand,
  score,
  previous_score: prev,
  drop,
  dropped,
  slipped,
  overtaken,
  alert: dropped || slipped || overtaken,
  recommended_count: rec,
  llm_count: total,
  share_of_voice_pct: sov,
  checked_at: item.checked_at,
} }];
